    class HugeToken : Token {
        constructor(value: String) : super(PREFIX, LENGTH, SEED, value)
        constructor(id: BigInteger) : super(PREFIX, LENGTH, SEED, id)

        companion object {
            const val PREFIX = "H"
            const val LENGTH = 20
            const val SEED = 0x99887766L
        }
    }

    @Test
    fun `UserToken roundtrips`() {
