        }
    }

    @Test
    fun `InvoiceToken roundtrips`() {
        for (id in 0L..20L) {
            val token = InvoiceToken(BigInteger.valueOf(id))
            assertEquals(BigInteger.valueOf(id), token.toId())
        }
    }

