        val encodedPart = canonical.value.substringAfter('_').dropLast(1)
        val checkPart = canonical.value.last()
        val lower = "U_${encodedPart.lowercase()}$checkPart"
        val fromLower = UserToken(lower)
        assertEquals(canonical, fromLower)
    }

